import re
import os

html_path = r"c:\Users\mimou\PlatformActia\static\index.html"

with open(html_path, "r", encoding="utf-8") as f:
    content = f.read()

# 1. Update API URLs for Mode B Intranet Deployment
content = content.replace(
    'const API_BASE = "http://localhost:8000/api/v1/auth";',
    'const API_BASE = window.location.origin + "/api/v1/auth";'
)
content = content.replace(
    'const API_AUDITS = "http://localhost:8000/api/v1/audits";',
    'const API_AUDITS = window.location.origin + "/api/v1/audits";'
)

# 2. Remove external CDN links
content = re.sub(r'<link rel="preconnect" href="https://fonts\.googleapis\.com">', '', content)
content = re.sub(r'<link rel="preconnect" href="https://fonts\.gstatic\.com" crossorigin>', '', content)
content = re.sub(r'<link href="https://fonts\.googleapis\.com/css2\?[^"]+" rel="stylesheet">', '', content)
content = re.sub(r'<link rel="stylesheet" href="https://cdnjs\.cloudflare\.com/ajax/libs/font-awesome/[^"]+">', '', content)

